impl<B: MemoriesBackend> ServerHandler for MemoriesMcpServer<B> {
    fn get_info(&self) -> ServerInfo {
        ServerInfo {
            instructions: Some(
                "Use these tools to list, read, and search Codex memory files.".to_string(),
            ),
            capabilities: ServerCapabilities::builder().enable_tools().build(),
            ..ServerInfo::default()
        }
    }

    fn list_tools(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: rmcp::service::RequestContext<rmcp::service::RoleServer>,
    ) -> impl std::future::Future<Output = Result<ListToolsResult, McpError>> + Send + '_ {
        let tools = Arc::clone(&self.tools);
        async move {
            Ok(ListToolsResult {
                tools: (*tools).clone(),
                next_cursor: None,
                meta: None,
            })
        }
    }

    async fn call_tool(
        &self,
        request: CallToolRequestParams,
        _context: rmcp::service::RequestContext<rmcp::service::RoleServer>,
    ) -> Result<CallToolResult, McpError> {
        let value = serde_json::Value::Object(
            request
                .arguments
                .unwrap_or_default()
                .into_iter()
                .collect::<serde_json::Map<String, serde_json::Value>>(),
        );
        let structured_content = match request.name.as_ref() {
            LIST_TOOL_NAME => {
                let args: ListArgs = parse_args(value)?;
                json!(
                    self.backend
                        .list(ListMemoriesRequest {
                            path: args.path,
                            cursor: args.cursor,
                            max_results: clamp_max_results(
                                args.max_results,
                                DEFAULT_LIST_MAX_RESULTS,
                                MAX_LIST_RESULTS,
                            ),
                        })
                        .await
                        .map_err(backend_error_to_mcp)?
                )
            }
            READ_TOOL_NAME => {
                let args: ReadArgs = parse_args(value)?;
                json!(
                    self.backend
                        .read(ReadMemoryRequest {
                            path: args.path,
                            line_offset: args.line_offset.unwrap_or(1),
                            max_lines: args.max_lines,
                            max_tokens: DEFAULT_READ_MAX_TOKENS,
                        })
                        .await
                        .map_err(backend_error_to_mcp)?
                )
            }
            SEARCH_TOOL_NAME => {
                let args: SearchArgs = parse_args(value)?;
                json!(
                    self.backend
                        .search(SearchMemoriesRequest {
                            query: args.query,
                            path: args.path,
                            cursor: args.cursor,
                            max_results: clamp_max_results(
                                args.max_results,
                                DEFAULT_SEARCH_MAX_RESULTS,
                                MAX_SEARCH_RESULTS,
                            ),
                        })
                        .await
                        .map_err(backend_error_to_mcp)?
                )
            }
            other => {
                return Err(McpError::invalid_params(
                    format!("unknown tool: {other}"),
                    None,
                ));
            }
        };

        Ok(CallToolResult {
            content: vec![Content::text(structured_content.to_string())],
            structured_content: Some(structured_content),
            is_error: Some(false),
            meta: None,
        })
    }
}

